package com.billbull.backend.pos.printer;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.junit.jupiter.api.DynamicTest;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.TestFactory;

import java.io.IOException;
import java.io.InputStream;
import java.util.ArrayList;
import java.util.List;

import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertNotNull;
import static org.junit.jupiter.api.Assertions.assertTrue;

/**
 * Real receipts and labels, generated by the real frontend builders
 * ({@code billbull-frontend/src/utils/__tests__/printerPayloadFixtures.test.js} writes
 * {@code src/test/resources/printer-payloads/}), checked by the server-side policies. The print
 * agent runs the same files through its own policies, so a builder change that one side would
 * refuse fails a test instead of a till.
 */
class PrinterPayloadFixturesTest {

    @Test
    void theFixtureSetCoversBothProtocols() throws IOException {
        List<JsonNode> all = manifest();
        assertTrue(all.stream().filter(m -> m.get("protocol").asText().equals("escpos")).count() >= 4);
        assertTrue(all.stream().filter(m -> m.get("protocol").asText().equals("zpl")).count() >= 4);
    }

    @TestFactory
    List<DynamicTest> eachPayloadPassesItsOwnPolicy() throws IOException {
        List<DynamicTest> tests = new ArrayList<>();
        for (JsonNode m : manifest()) {
            String file = m.get("file").asText();
            boolean zpl = m.get("protocol").asText().equals("zpl");
            tests.add(DynamicTest.dynamicTest(file, () -> {
                byte[] bytes = read(file);
                PrintCommandVerdict own = (zpl ? PrinterCommandProtocol.ZPL : PrinterCommandProtocol.ESCPOS).inspect(bytes);
                assertTrue(own.allowed(), () -> file + ": " + own);
                assertFalse(own.drawerPulse(), () -> file + " must not open a drawer");
                // Binary ESC/POS is never a well-formed label. The reverse does not hold — a label
                // is printable text to the ESC/POS walker — which is why the stored printer's type,
                // not the walker, keeps labels and receipts apart (PrinterCommandProtocol.of).
                if (!zpl) {
                    PrintCommandVerdict asLabel = PrinterCommandProtocol.ZPL.inspect(bytes);
                    assertFalse(asLabel.allowed(), () -> file + " passed the ZPL policy");
                }
            }));
        }
        return tests;
    }

    static List<JsonNode> manifest() throws IOException {
        List<JsonNode> out = new ArrayList<>();
        new ObjectMapper().readTree(read("manifest.json")).forEach(out::add);
        return out;
    }

    static byte[] read(String name) throws IOException {
        try (InputStream in = PrinterPayloadFixturesTest.class.getResourceAsStream("/printer-payloads/" + name)) {
            assertNotNull(in, "missing fixture " + name + " — regenerate it from the frontend test");
            return in.readAllBytes();
        }
    }
}
